#!/usr/bin/env python3
"""Patch the iOS project generated by `flutter create` for ONE.
Usage: python3 tool/patch_ios.py mobile   (run on macOS; sounds are added to the Xcode project with the xcodeproj gem)
"""
import json, pathlib, plistlib, re, shutil, subprocess, sys

root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else "mobile")
ios = root / "ios"
runner = ios / "Runner"
tool = pathlib.Path(__file__).parent

# ── Info.plist: name, languages, permission texts, background modes ──
pl = runner / "Info.plist"
info = plistlib.loads(pl.read_bytes())
loc = "ONE يستخدم موقعك داخل حدود مناطق العمل فقط لإيصال إنذارات منطقتك وحصرك عند الطوارئ. / ONE uses your location inside work boundaries only, to deliver your area's alarms and muster you in an emergency."
info.update({
    "CFBundleDisplayName": "ONE",
    "CFBundleName": "ONE",
    "CFBundleDevelopmentRegion": "ar",
    "CFBundleLocalizations": ["ar", "en"],
    "NSLocationWhenInUseUsageDescription": loc,
    "NSLocationAlwaysAndWhenInUseUsageDescription": loc,
    "NSLocationAlwaysUsageDescription": loc,
    "NSCameraUsageDescription": "لتصوير بلاغات 160 / To photograph 160 reports",
    "NSPhotoLibraryUsageDescription": "لإرفاق صور ببلاغات 160 / To attach photos to 160 reports",
    "NSMicrophoneUsageDescription": "للمكالمات الصوتية مع ORT / For voice calls with ORT",
    "NSFaceIDUsageDescription": "للدخول إلى ONE بالوجه / To sign in to ONE with Face ID",
    "UIBackgroundModes": ["location", "audio", "fetch"],
    "ITSAppUsesNonExemptEncryption": False,
})
pl.write_bytes(plistlib.dumps(info))

# ── Podfile: iOS 14 + permission_handler switches (without them its requests always return "denied") ──
(ios / "Podfile").write_text("""platform :ios, '14.0'
ENV['COCOAPODS_DISABLE_STATS'] = 'true'

project 'Runner', {
  'Debug' => :debug,
  'Profile' => :release,
  'Release' => :release,
}

def flutter_root
  generated_xcode_build_settings_path = File.expand_path(File.join('..', 'Flutter', 'Generated.xcconfig'), __FILE__)
  unless File.exist?(generated_xcode_build_settings_path)
    raise "#{generated_xcode_build_settings_path} must exist. Run flutter pub get first"
  end
  File.foreach(generated_xcode_build_settings_path) do |line|
    matches = line.match(/FLUTTER_ROOT\\=(.*)/)
    return matches[1].strip if matches
  end
  raise "FLUTTER_ROOT not found in #{generated_xcode_build_settings_path}"
end

require File.expand_path(File.join('packages', 'flutter_tools', 'bin', 'podhelper'), flutter_root)

flutter_ios_podfile_setup

target 'Runner' do
  use_frameworks!
  flutter_install_all_ios_pods File.dirname(File.realpath(__FILE__))
end

post_install do |installer|
  installer.pods_project.targets.each do |target|
    flutter_additional_ios_build_settings(target)
    target.build_configurations.each do |config|
      config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '14.0'
      config.build_settings['GCC_PREPROCESSOR_DEFINITIONS'] ||= [
        '$(inherited)',
        'PERMISSION_LOCATION=1',
        'PERMISSION_LOCATION_WHENINUSE=0',
        'PERMISSION_NOTIFICATIONS=1',
        'PERMISSION_CAMERA=1',
        'PERMISSION_MICROPHONE=1',
        'PERMISSION_PHOTOS=1',
      ]
    end
  end
end
""")

# ── deployment target in the Runner project ──
pbx = ios / "Runner.xcodeproj/project.pbxproj"
p = pbx.read_text()
p = re.sub(r"IPHONEOS_DEPLOYMENT_TARGET = [\d.]+;", "IPHONEOS_DEPLOYMENT_TARGET = 14.0;", p)
pbx.write_text(p)

# ── app icon: single 1024 universal icon (Xcode 14+) ──
icon_dir = runner / "Assets.xcassets/AppIcon.appiconset"
shutil.rmtree(icon_dir, ignore_errors=True)
icon_dir.mkdir(parents=True)
shutil.copy(tool / "icons/icon-1024.png", icon_dir / "icon-1024.png")
(icon_dir / "Contents.json").write_text(json.dumps({
    "images": [{"filename": "icon-1024.png", "idiom": "universal", "platform": "ios", "size": "1024x1024"}],
    "info": {"author": "xcode", "version": 1},
}, indent=2))

# ── signal tones as notification sounds (must be in the app bundle) ──
for f in (root / "assets/sounds").glob("*.wav"):
    shutil.copy(f, runner / f.name)
ruby = """
require 'xcodeproj'
p = Xcodeproj::Project.open('%s')
t = p.targets.find { |x| x.name == 'Runner' }
g = p.main_group.find_subpath('Runner')
%%w(signal1.wav signal2.wav signal3.wav).each do |f|
  next if g.files.any? { |r| r.path == f }
  t.resources_build_phase.add_file_reference(g.new_reference(f))
end
p.save
""" % (ios / "Runner.xcodeproj").resolve()
subprocess.run(["ruby", "-e", ruby], check=True)
print("iOS patched")
